<script setup lang="ts">
import MarkdownText from './MarkdownText.vue'
import {computed} from 'vue'
import type {GradingDetails,RubricPoint} from '../types'
import {calculateGrade,newReviewer} from '../grading'
const props=withDefaults(defineProps<{rubric?:RubricPoint[];readonly?:boolean;teacherOnly?:boolean}>(),{rubric:()=>[]})
const model=defineModel<GradingDetails>({required:true})
const points=computed(()=>props.readonly && model.value.rubric ? model.value.rubric:props.rubric)
const result=computed(()=>{try{return {score:calculateGrade(model.value,points.value),error:''}}catch(e){return {score:undefined,error:(e as Error).message}}})
</script>
<template><div class="score-editor"><div class="section-head"><h3>{{teacherOnly ? '教师评分' : '评分人员与权重'}}</h3><el-button v-if="!readonly && !teacherOnly" size="small" :disabled="model.reviewers.length>=20" @click="model.reviewers.push({...newReviewer(),weight:0})">增加评分人员</el-button></div><p v-if="!teacherOnly" class="muted">教师录入并确认评分。各人员权重合计 100%，综合得分由系统计算。</p><div v-for="(r,index) in model.reviewers" :key="index" class="phase-form"><div v-if="!teacherOnly" class="form-grid"><el-form-item label="评分人员"><el-input v-model="r.name" :disabled="readonly" /></el-form-item><el-form-item label="权重（%）"><el-input-number v-model="r.weight" :min="0" :max="100" :precision="2" :disabled="readonly" /></el-form-item></div><template v-if="points.length"><div v-for="p in points" :key="p.id" class="rubric-score-row"><div><strong>{{p.dimension}} / {{p.title}}</strong><MarkdownText class="muted" :text="p.description" /></div><el-input-number v-model="r.points[p.id]" :min="0" :max="p.maxPoints" :precision="2" :disabled="readonly" :aria-label="r.name+' '+p.title" /><span>/ {{p.maxPoints}}</span></div></template><el-form-item v-else label="分数（100 分制）"><el-input-number v-model="r.score" :min="0" :max="100" :precision="2" :disabled="readonly" /></el-form-item><el-form-item label="评分备注"><el-input v-model="r.comment" :disabled="readonly" /></el-form-item><el-button v-if="!readonly && model.reviewers.length>1" text type="danger" @click="model.reviewers.splice(index,1)">移除评分人员</el-button></div><p v-if="result.error && !readonly" class="error-text">{{result.error}}</p><div v-else class="info-strip">综合得分：<strong>{{model.score ?? result.score ?? '—'}}</strong> / 100</div><p class="muted">{{model.formula || (points.length?'人员得分 = 观测点得分之和 ÷ 观测点满分之和 × 100；任务成绩 = Σ（人员得分 × 权重%）':'任务成绩 = Σ（人员百分制分数 × 权重%）')}}</p><small v-if="model.recordedBy" class="muted">记录并确认：{{model.recordedBy}} · 以下为该次评分采用的规则</small></div></template>
